"""Summarise saved measurements only; no repeated geometry calculation."""
import pathlib,json
R=pathlib.Path(__file__).resolve().parent
rows=[]
for owner in ['metacarpal_1_left','metacarpal_3_left']:
    fit=json.loads((R/(owner+'-registration.json')).read_text())
    neighbours=json.loads((R/(owner+'-neighbors-summary.json')).read_text())
    shaft=min((x for x in fit['fits'] if x['mode']=='shaft60'),key=lambda x:x['symmetrical_sample_point_rms_mm'])
    selfscan=json.loads((R/(owner+'-self.json')).read_text())
    collisions=[]
    for x in neighbours['results']:
        if x.get('counts',{}).get('crossing') or x.get('counts',{}).get('coplanarOverlap'):
            collisions.append({'neighbor':x['neighbor'],'crossingTrianglePairs':x['counts'].get('crossing',0),'candidateIntoNeighborDepthMM':x['candidateIntoNeighbor']['maxSampleDepthMM'],'neighborIntoCandidateDepthMM':x['neighborIntoCandidate']['maxSampleDepthMM'],'depthComplete':x['candidateIntoNeighbor']['complete'] and x['neighborIntoCandidate']['complete'],'evidence':owner+'-neighbor-'+x['neighbor']+'.json'})
    rows.append({'id':owner,'issueId':'GEO-HAND-LEFT-MODELS','status':'test_only','admitted':False,'productionChanged':False,'noModelRemoved':False,'testGLB':owner+'-rigid-trial-v2.glb','method':'PCA main axis signed away from named carpals; 4 quarter-turn starts; symmetric whole-surface rigid ICP. Separate shaft60 fits assess sensitivity. No scale/reflection/deformation and no neighbour-dependent objective. Source patient LPS translated into current Three world through one saved proper rigid matrix for each candidate.','sourceLengthAlongPCAmm':fit['source_long_axis_extent_mm'],'BP3DLengthAlongPCAmm':fit['target_long_axis_extent_mm'],'bestPointCloudRMSmm':fit['chosen']['symmetrical_sample_point_rms_mm'],'longAxisCosine':fit['chosen']['long_axis_alignment_cosine'],'shaftSensitivity':{'rotationDegrees':shaft['rotation_from_best_deg'],'rmsSourcePointDisplacementMM':shaft['rms_displacement_from_best_mm'],'note':'Shape registration depends on weighting of shaft and endpoints; no accepted anatomical base/head landmarks are encoded.'},'surfaceDistances':json.loads((R/(owner+'-surface-distances.json')).read_text()),'collisionPairs':collisions,'workingNeighborCount':neighbours['workingNeighbors'],'selfIntersection':{'complete':selfscan['complete'],'counts':selfscan['counts']},'blocker':'New donor shape can be rigidly aligned approximately, but residual intersections with working base/head neighbours remain. Surface assignment and anatomical pose not independently confirmed; choosing another transform solely to remove collisions would be unsupported. This is not a claim that the source bone is intrinsically pathological or unusable as a separately identified specimen.','nextStep':'Review saved Blender views for base/head/shaft orientation and recorded crossing patches. Confirm anatomical landmarks before changing registration; if no coherent pose exists, evaluate the complete matched-donor region separately, preserving working BP3D neighbours.','evidence':[owner+'-registration.json',owner+'-surface-distances.json',owner+'-neighbors-summary.json',owner+'-self.json']})
header=json.loads((R/'foot-header-retrieval.json').read_text())
meta=header.get('metadata',{})
image=json.loads((R/'bonehub-ct-file-metadata.json').read_text())
out={'schemaVersion':1,'date':'2026-10-22','scope':'New BoneHub MC I/III rigid shape-registration and bounded foot image-header followup only','priorReview':'../geometry-recovery-bone-methods-2026-10-22T07-10-36-377Z-kDATcr/bone-method-decisions.json','structures':rows,'technicalExportCorrection':'First trial exports had no NORMAL attribute. They remain saved. v2 uses same saved positions/triangle indices with explicit vertex normals; registration not repeated. 64 Node checks passed on v2.','tests':{'NodeGLB':'trial-glb-node-checks.json','passedNodeChecks':64,'BVH':'indirect:true; unchanged indices; all new candidate/current regional-neighbour pairs AABB/BVH; vertex/face-centre sampled depth in both directions for crossings','trimesh':'new-source topology and saved rigid transforms; originals untouched','Blender':'scenario prepared for parent agent; check owner-blender.json outputs when produced, no visual admission recorded by this summary','Playwright':'not run by this agent; test-only resources are not integrated into application'},'BlenderScenario':'blender_review_metacarpal.py','footMedicalImageCheckpoint':{'status':header['status'],'sourceCommit':header['commit'],'header':'bonehub-male-foot-header.nrrd.txt','metadata':'foot-header-retrieval.json','bytesRead':header.get('bytesRead'),'httpStatus':header.get('httpStatus'),'fullVolumeDownloaded':False,'sizes':meta.get('sizes'),'spacingMM':'0.9375 x 0.9375 x1.0 according to space directions','orientation':meta.get('space'),'origin':meta.get('space origin'),'dimensions':meta.get('dimension'),'segmentNames':[v for k,v in meta.items() if k.endswith('_Name')],'decision':'17 labels; phalanges remain grouped by toe (five PHALANGE_FOOT labels), not proximal/middle/distal. The header does not supply separate joint boundaries. CT image of same male is public/pinned but has not been read or segmented.','CT':image['files'],'nextStep':'Retrieve the male CT only for a bounded planned image investigation, inspect alignment and joint gaps against this seg.nrrd, then annotate independent toe phalanges. Do not claim grouped labels resolve existing individual phalanx noModel.'},'summary':{'newModelsIntegrated':0,'noModelRemoved':0,'testDerivativeGLB':2,'examinedBones':2,'boneNoModelScopeUnchanged':20}}
(R/'decision.json').open('x',encoding='utf8').write(json.dumps(out,ensure_ascii=False,indent=2))
print(json.dumps(out['summary']))
